                this.interim[0] = byte1;
                return size;
            }
            byte2 = input[i++];
            if ((byte2 & 0xC0) !== 0x80) {
                // wrong continuation
                i--;
                continue;
            }
            if (i >= length) {
                this.interim[0] = byte1;
                this.interim[1] = byte2;
                return size;
            }
            byte3 = input[i++];
            if ((byte3 & 0xC0) !== 0x80) {
                // wrong continuation
                i--;
                continue;
            }
            if (i >= length) {
                this.interim[0] = byte1;
                this.interim[1] = byte2;
                this.interim[2] = byte3;
                return size;
            }
            byte4 = input[i++];
            if ((byte4 & 0xC0) !== 0x80) {
                // wrong continuation
                i--;
                continue;
            }
            codepoint = (byte1 & 0x07) << 18 | (byte2 & 0x3F) << 12 | (byte3 & 0x3F) << 6 | (byte4 & 0x3F);
            if (codepoint < 0x010000 || codepoint > 0x10FFFF) {
                // illegal codepoint, no i-- here
                continue;
            }
            target[size++] = codepoint;
        }
        else {
            // illegal byte, just skip
        }
    }
    return size;
}

